css:
.app.p02-app { grid-template-columns: minmax(0, 1fr); grid-template-rows: minmax(0, 1fr); grid-template-areas: "content"; }
.content.p02-stage { height: 100%; display: grid; place-items: center; }
.p02-text { font-size: var(--fs-body); line-height: var(--lh-body); }
.p02-notice { padding: var(--s-3) var(--s-4) 0; }
.p02-foot .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p02-updated { display: block; }
.p02-e { --frame-w: var(--w2); }
